const LanguageContext = createContext();

const LANGUAGE_KEY = 'appLanguage';

export function LanguageProvider({ children }) {
  const [language, setLanguageState] = useState(() => {
    return localStorage.getItem(LANGUAGE_KEY) || 'en';
  });

  // Persist locally on every change
  useEffect(() => {
    localStorage.setItem(LANGUAGE_KEY, language);
  }, [language]);

  // On login (token appears), pull language from the user's account.
  // Account preference wins over local — the account is the source of truth.
  useEffect(() => {
    const storedToken = localStorage.getItem('token');
    if (!storedToken) return;
    let cancelled = false;
    authApi.me()
      .then((res) => {
        if (cancelled) return;
        const acctLang = res.data?.user?.language || res.data?.language;
        if (acctLang && acctLang !== localStorage.getItem(LANGUAGE_KEY)) {
          setLanguageState(acctLang);
          localStorage.setItem(LANGUAGE_KEY, acctLang);
        }
      })
      .catch(() => {});
    return () => { cancelled = true; };
  }, []);

  // setLanguage: updates local state + persists to the account when logged in
  const setLanguage = (lang) => {
    setLanguageState(lang);
    localStorage.setItem(LANGUAGE_KEY, lang);

    if (localStorage.getItem('token')) {
      authApi.updateLanguage(lang).then((res) => {
        // Keep cached user record in sync so refreshes keep the preference
        try {
          const cached = JSON.parse(localStorage.getItem('user') || 'null');
          const serverUser = res.data?.user;
          if (cached && serverUser) {
            localStorage.setItem('user', JSON.stringify({ ...cached, language: serverUser.language || lang }));
          }
        } catch { /* ignore parse errors */ }
      }).catch(() => { /* offline: local pref still applies */ });
    }
  };

  const t = (key, fallback = '') => {
    if (!key) return '';
    const val = translations[language]?.[key] || translations.en?.[key];
    if (val) return val;
    if (fallback) return fallback;
    return key.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t, translations }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
}
